int ppp_register_channel(struct net *net, struct ppp_channel *chan) {
    struct ppp_channel *new_chan;
    int ret = -ENOMEM;

    new_chan = kmalloc(sizeof(*new_chan), GFP_KERNEL);
    if (!new_chan)
        goto out;

    *new_chan = *chan;
    new_chan->next = NULL;

    write_lock(&ppp_lock);
    if (ppp_channels) {
        struct ppp_channel *tmp;
        tmp = ppp_channels;
        while (tmp->next)
            tmp = tmp->next;
        tmp->next = new_chan;
    } else {
        ppp_channels = new_chan;
    }
    ppp_num_channels++;
    write_unlock(&ppp_lock);

    ret = 0;
out:
    return ret;
}
